// GENERATED from tool translation tables, then hand-maintained.
// UI strings that are not in AppLocalizations getters: the key is the
// source text as written at the call site, the value is [az, en, ru, ar].
// Use tr('…') for plain text and trf('… {name} …', {'name': v}) for text
// with values. test/l10n_audit_test.dart checks every call site has an entry.
import 'app_localizations.dart';

String tr(String key) {
  final v = uiStrings[key];
  if (v == null) return key;
  return v[AppLocalizations().language.index];
}

String trf(String key, Map<String, Object> args) {
  var s = tr(key);
  args.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}

/// Every translation of [key] (for recognising text written in any UI language).
Set<String> trAll(String key) => {key, ...?uiStrings[key]};

